{"command": "$files = Get-ChildItem src -Recurse -Include *.vue -File
foreach ($f in $files) {
  $rel = $f.FullName.Replace((Get-Location).Path+'\','')
  $lines = Get-Content $f.FullName -Encoding UTF8
  $hits = @()
  for ($i=0; $i -lt $lines.Count; $i++) {
    $l = $lines[$i]
    if ($l -match '[\u4e00-\u9fff]') {
      $t = $l.TrimStart()
      if ($t.StartsWith('//') -or $t.StartsWith('*') -or $t.StartsWith('/*') -or $t.StartsWith('<!--')) { continue }
      $hits += ("{0}: {1}" -f ($i+1), $t)
    }
  }
  if ($hits.Count -gt 0) { "=== $rel ($($hits.Count)) ==="; $hits | ForEach-Object { $_ } }
}", "description": "List non-comment Chinese lines per vue file"}

