  i18n.locale = locale;
  termStore.locale = locale;
  syncElementLocale(locale);
  document.documentElement.setAttribute("lang", locale === "zh-CN" ? "zh-CN" : "en");
  if (persist) { try { window.localStorage.setItem(LOCALE_STORAGE_KEY, settingVal); } catch(e){} }
  return locale;
}

