{"file_path": "D:\ZZH\aska\github\shunkai-dg\src\utils\theme.js", "content": "/**
 * 主题「昼夜」控制
 * ---------------------------------------------------------------
 * 白天（day）  ：浅蓝 #D6E8F5 底 + 中蓝 #4A90C4 强调 + 深灰蓝 #1A2B3C 文字
 * 黑夜（night）：深蓝 #0B1A2F 底 + 亮蓝 #5AA9E6 强调 + 浅雾蓝 #E8F1F8 文字
 * 跟随系统（auto）：读取 prefers-color-scheme，系统切换时自动跟随
 *
 * 落地方式：把解析后的主题写到 <html data-theme="day|night">，
 * 具体色值由 src/assets/css/theme.css 中的 CSS 变量提供。
 * 切换时给 <html> 临时挂 .theme-transition（300ms 缓动，背景与文字同步渐变）。
 */

export const THEME_STORAGE_KEY = "aska-theme";

export const THEME_DAY = "day";
export const THEME_NIGHT = "night";
export const THEME_AUTO = "auto";

/** 三种可选模式（顺序即菜单顺序） */
export const THEME_MODES = [THEME_DAY, THEME_NIGHT, THEME_AUTO];

/** 过渡类名与时长（300ms 缓动 + 少量余量，避免提前撤掉） */
const TRANSITION_CLASS = "theme-transition";
const TRANSITION_DURATION = 400;

let transitionTimer = null;
let mediaQuery = null;
let mediaBound = false;
let currentMode = THEME_AUTO;

/** 系统当前偏好：dark -> night，其余 -> day */
export function getSystemTheme() {
  if (typeof window === "undefined" || !window.matchMedia) return THEME_DAY;
  return window.matchMedia("(prefers-color-scheme: dark)").matches
    ? THEME_NIGHT
    : THEME_DAY;
}

/** 模式 -> 实际生效主题 */
export function resolveTheme(mode) {
  if (!mode || mode === THEME_AUTO) return getSystemTheme();
  return mode === THEME_NIGHT ? THEME_NIGHT : THEME_DAY;
}

/** 非法值一律回落到跟随系统 */
export function normalizeThemeMode(mode) {
  return THEME_MODES.indexOf(mode) === -1 ? THEME_AUTO : mode;
}

/** 读取用户选择（localStorage），默认跟随系统 */
export function readThemeMode() {
  try {
    const saved = window.localStorage.getItem(THEME_STORAGE_KEY);
    if (saved && THEME_MODES.indexOf(saved) !== -1) return saved;
  } catch (e) {
    /* 隐私模式等场景忽略 */
  }
  return THEME_AUTO;
}

/** 切换期间开启全局颜色过渡（结束后移除，不影响常态 hover 手感） */
function setTransition(on) {
  if (typeof document === "undefined") return;
  const root = document.documentElement;
  if (transitionTimer) {
    clearTimeout(transitionTimer);
    transitionTimer = null;
  }
  if (!on) {
    root.classList.remove(TRANSITION_CLASS);
    return;
  }
  root.classList.add(TRANSITION_CLASS);
  transitionTimer = setTimeout(() => {
    root.classList.remove(TRANSITION_CLASS);
    transitionTimer = null;
  }, TRANSITION_DURATION);
}

/**
 * 应用主题
 * @param {string} mode day | night | auto
 * @param {{animate?: boolean, persist?: boolean}} [options]
 * @returns {string} 实际生效的主题 day | night
 */
export function applyTheme(mode, options) {
  const opts = options || {};
  const nextMode = normalizeThemeMode(mode);
  const theme = resolveTheme(nextMode);

  if (typeof document === "undefined") return theme;

  const root = document.documentElement;
  const previous = root.getAttribute("data-theme");
  const changed = previous !== theme;
  // 首屏（还没有 data-theme）不做动画，避免加载时闪一下
  if (opts.animate !== false && changed && previous) setTransition(true);

  root.setAttribute("data-theme", theme);
  root.setAttribute("data-theme-mode", nextMode);
  root.style.colorScheme = theme === THEME_NIGHT ? "dark" : "light";

  currentMode = nextMode;

  if (opts.persist !== false) {
    try {
      window.localStorage.setItem(THEME_STORAGE_KEY, nextMode);
    } catch (e) {
      /* 忽略写入失败 */
    }
  }
  return theme;
}

/** 语义化入口：设置用户选择并立即生效 + 持久化 */
export function setThemeMode(mode, options) {
  return applyTheme(mode, options);
}

/** 系统主题变化监听：仅在「跟随系统」时自动跟随 */
function bindSystemThemeListener() {
  if (
    mediaBound ||
    typeof window === "undefined" ||
    !window.matchMedia
  ) {
    return;
  }
  mediaQuery = window.matchMedia("(prefers-color-scheme: dark)");
  const handler = () => {
    if (currentMode === THEME_AUTO) {
      applyTheme(THEME_AUTO, { persist: false });
    }
  };
  if (mediaQuery.addEventListener) {
    mediaQuery.addEventListener("change", handler);
  } else if (mediaQuery.addListener) {
    // 兼容旧内核
    mediaQuery.addListener(handler);
  }
  mediaBound = true;
}

/** 启动时调用：读取偏好、无动画应用、绑定系统监听 */
export function initTheme() {
  const mode = readThemeMode();
  applyTheme(mode, { animate: false, persist: false });
  bindSystemThemeListener();
  return mode;
}

/** 当前生效主题（不想读 DOM 时使用） */
export function getCurrentTheme() {
  if (typeof document !== "undefined") {
    const attr = document.documentElement.getAttribute("data-theme");
    if (attr === THEME_DAY || attr === THEME_NIGHT) return attr;
  }
  return resolveTheme(currentMode);
}

export default {
  THEME_STORAGE_KEY,
  THEME_DAY,
  THEME_NIGHT,
  THEME_AUTO,
  THEME_MODES,
  getSystemTheme,
  resolveTheme,
  normalizeThemeMode,
  readThemeMode,
  applyTheme,
  setThemeMode,
  initTheme,
  getCurrentTheme,
};
"}

{"file_path": "D:\ZZH\aska\github\shunkai-dg\src\i18n\index.js", "content": "/**
 * 国际化入口（vue-i18n@8）
 * ---------------------------------------------------------------
 * 支持：中文（zh-CN）/ 英文（en-US）/ 跟随系统（auto）
 * - 语言模块按目录自动装载：./lang/zh-CN/*.js、./lang/en-US/*.js
 *   每个文件一个命名空间（文件名即命名空间，如 product.js -> $t('product.xxx')）
 * - 同时联动 ElementUI 内置文案与 <html lang>
 * - 选择结果写入 localStorage；跟随系统时监听 languagechange
 */
import Vue from "vue";
import VueI18n from "vue-i18n";
import ElementLocale from "element-ui/lib/locale";
import elementZhCN from "element-ui/lib/locale/lang/zh-CN";
import elementEnUS from "element-ui/lib/locale/lang/en";
import { termStore, translateTerm } from "./terms";

Vue.use(VueI18n);

export const LOCALE_STORAGE_KEY = "aska-locale";
export const LOCALE_ZH = "zh-CN";
export const LOCALE_EN = "en-US";
export const LOCALE_AUTO = "auto";
export const SUPPORTED_LOCALES = [LOCALE_ZH, LOCALE_EN];
/** 站点原始文案为英文，缺失译文时回退英文 */
export const DEFAULT_LOCALE = LOCALE_EN;

/** 装载某语言目录下所有命名空间模块 */
function loadModules(context) {
  const messages = {};
  context.keys().forEach((key) => {
    const name = key.replace(/^\.\//, "").replace(/\.js$/, "");
    const mod = context(key);
    messages[name] = (mod && mod.default) || mod || {};
  });
  return messages;
}

const messages = {
  [LOCALE_ZH]: loadModules(require.context("./lang/zh-CN", false, /\.js$/)),
  [LOCALE_EN]: loadModules(require.context("./lang/en-US", false, /\.js$/)),
};

/** 系统语言 -> 支持的 locale（中文系一律 zh-CN，其余 en-US） */
export function detectSystemLocale() {
  const nav =
    (typeof navigator !== "undefined" &&
      ((navigator.languages && navigator.languages[0]) || navigator.language)) ||
    "";
  return /^zh/i.test(nav) ? LOCALE_ZH : LOCALE_EN;
}

export function isValidLocale(locale) {
  return SUPPORTED_LOCALES.indexOf(locale) !== -1;
}

/** 用户选择（含 auto）-> 实际 locale */
export function resolveLocale(setting) {
  if (!setting || setting === LOCALE_AUTO) return detectSystemLocale();
  return isValidLocale(setting) ? setting : DEFAULT_LOCALE;
}

/** 读取用户选择，非法/未设置时回落到跟随系统 */
export function readLocaleSetting() {
  try {
    const saved = window.localStorage.getItem(LOCALE_STORAGE_KEY);
    if (saved === LOCALE_AUTO || isValidLocale(saved)) return saved;
  } catch (e) {
    /* 忽略 */
  }
  return LOCALE_AUTO;
}

export function normalizeLocaleSetting(setting) {
  return setting === LOCALE_AUTO || isValidLocale(setting) ? setting : LOCALE_AUTO;
}

const i18n = new VueI18n({
  locale: resolveLocale(readLocaleSetting()),
  fallbackLocale: DEFAULT_LOCALE,
  messages,
  silentTranslationWarn: true,
  silentFallbackWarn: true,
});

/** 同步 ElementUI 内置文案 */
function syncElementLocale(locale) {
  ElementLocale.use(locale === LOCALE_ZH ? elementZhCN : elementEnUS);
}

/**
 * 应用语言
 * @param {string} setting zh-CN | en-US | auto
 * @param {{persist?: boolean}} [options]
 * @returns {string} 实际生效的 locale
 */
export function applyLocale(setting, options) {
  const opts = options || {};
  const normalized = normalizeLocaleSetting(setting);
  const locale = resolveLocale(normalized);

  i18n.locale = locale;
  // 供分类词典等非 message 文案使用（触发已订阅组件的重渲染）
  termStore.locale = locale;
  syncElementLocale(locale);

  if (typeof document !== "undefined") {
    document.documentElement.setAttribute(
      "lang",
      locale === LOCALE_ZH ? "zh-CN" : "en",
    );
  }
  if (opts.persist !== false) {
    try {
      window.localStorage.setItem(LOCALE_STORAGE_KEY, normalized);
    } catch (e) {
      /* 忽略 */
    }
  }
  return locale;
}

/**
 * 跟随系统时监听系统语言变化
 * @param {() => string} getSetting 返回当前用户选择
 */
export function bindSystemLocaleListener(getSetting) {
  if (typeof window === "undefined" || !window.addEventListener) return;
  window.addEventListener("languagechange", () => {
    if (normalizeLocaleSetting(getSetting && getSetting()) === LOCALE_AUTO) {
      applyLocale(LOCALE_AUTO, { persist: false });
    }
  });
}

/** 启动时调用：应用语言 + 绑定系统语言监听 */
export function initLocale() {
  const setting = readLocaleSetting();
  applyLocale(setting, { persist: false });
  bindSystemLocaleListener(readLocaleSetting);
  return setting;
}

/** 语言下拉只展示语言本身（中文 / English），跟随系统项跟随界面语言 */
export const LOCALE_OPTIONS = [
  { value: LOCALE_ZH, label: "中文" },
  { value: LOCALE_EN, label: "English" },
  { value: LOCALE_AUTO, labelKey: "common.lang.auto" },
];

// 术语词典注入为全局方法：模板里 {{ $tt(cat.title) }}
Vue.mixin({
  methods: {
    /** 翻译分类等非 message 术语，查不到原样返回 */
    $tt(text) {
      return translateTerm(text);
    },
  },
});

export { translateTerm, termStore };
export default i18n;
"}

