{"content": "/* ============================================================================
   主题「昼夜」Day & Night
   ----------------------------------------------------------------------------
   浅蓝是白昼的呼吸，深蓝是夜晚的静默；同一片蓝，两种节奏。

   白天（day）  #D6E8F5 页面底色 · #4A90C4 中蓝强调 · #1A2B3C 正文
   黑夜（night）#0B1A2F 夜色底色 · #5AA9E6 亮蓝强调 · #E8F1F8 正文

   生效方式：src/utils/theme.js 把解析后的主题写到 <html data-theme="day|night">，
   本文件是所有色值的唯一来源（设计令牌见下方 :root）。
   切换动画：切换瞬间给 <html> 加 .theme-transition，300ms 缓动同步渐变。
   ========================================================================== */

/* ---------------------------------------------------------------------------
   1. 设计令牌
   ------------------------------------------------------------------------- */
:root {
  /* 品牌双色（规范原值，其它令牌均由它们派生） */
  --brand-day-bg: #d6e8f5;
  --brand-day-accent: #4a90c4;
  --brand-night-bg: #0b1a2f;
  --brand-night-accent: #5aa9e6;
  --brand-text-day: #1a2b3c;
  --brand-text-night: #e8f1f8;
}

/* 白天：晴日天空的柔和浅蓝 */
:root,
:root[data-theme="day"] {
  --bg: #d6e8f5; /* 页面背景 */
  --bg-soft: #e4f0f9; /* 页脚 / 次级区块 */
  --surface: #ffffff; /* 卡片、面板 */
  --surface-2: #eaf3fa; /* 卡片内次级块、条纹 */
  --surface-3: #dceaf6; /* 更弱的分区底色 */
  --text: #1a2b3c; /* 正文、标题（对比度 > 7:1） */
  --text-strong: #12202e;
  --text-muted: #47607a; /* 次要文字 */
  --text-faint: #67809a;
  --text-invert: #ffffff; /* 深色底上的文字 */
  --accent: #4a90c4; /* 按钮 / 链接 / 图标 */
  --accent-strong: #3579ab; /* hover */
  --accent-soft: rgba(74, 144, 196, 0.12);
  --accent-contrast: #ffffff; /* 强调色底上的文字 */
  --border: rgba(26, 43, 60, 0.14);
  --border-strong: rgba(26, 43, 60, 0.3);
  --header-bg: #d6e8f5;
  --header-text: #1a2b3c;
  --header-border: rgba(26, 43, 60, 0.1);
  --footer-bg: #e4f0f9;
  --footer-text: #1a2b3c;
  --hover-bg: #eaf3fa;
  --overlay: rgba(11, 26, 47, 0.5);
  --shadow-sm: 0 2px 8px rgba(26, 43, 60, 0.08);
  --shadow: 0 8px 24px rgba(26, 43, 60, 0.12);
  --focus-ring: 0 0 0 2px rgba(74, 144, 196, 0.35);
  --scroll-track: #e4f0f9;
  --scroll-thumb: #a9c9e2;
  --logo-filter: none;
  --btn-bg: #4a90c4;
  --btn-text: #ffffff;
  --input-bg: #ffffff;
}

/* 黑夜：接近午夜天空的深蓝 */
:root[data-theme="night"] {
  --bg: #0b1a2f;
  --bg-soft: #0e2038;
  --surface: #12253f;
  --surface-2: #162f4f;
  --surface-3: #1b3a5e;
  --text: #e8f1f8; /* 浅雾蓝，避免纯白眩光 */
  --text-strong: #ffffff;
  --text-muted: #a8c0d6;
  --text-faint: #8299b0;
  --text-invert: #0b1a2f;
  --accent: #5aa9e6;
  --accent-strong: #7fc0f2;
  --accent-soft: rgba(90, 169, 230, 0.16);
  --accent-contrast: #06121f;
  --border: rgba(232, 241, 248, 0.16);
  --border-strong: rgba(232, 241, 248, 0.32);
  --header-bg: #0b1a2f;
  --header-text: #e8f1f8;
  --header-border: rgba(232, 241, 248, 0.12);
  --footer-bg: #091627;
  --footer-text: #e8f1f8;
  --hover-bg: #162f4f;
  --overlay: rgba(4, 12, 24, 0.66);
  --shadow-sm: 0 2px 8px rgba(0, 0, 0, 0.4);
  --shadow: 0 8px 26px rgba(0, 0, 0, 0.5);
  --focus-ring: 0 0 0 2px rgba(90, 169, 230, 0.45);
  --scroll-track: #0b1a2f;
  --scroll-thumb: #2c4a6e;
  --logo-filter: brightness(0) invert(1) opacity(0.92);
  --btn-bg: #5aa9e6;
  --btn-text: #06121f;
  --input-bg: #12253f;
}

/* ---------------------------------------------------------------------------
   2. 基础层
   ------------------------------------------------------------------------- */
html {
  background-color: var(--bg);
}

body {
  background-color: var(--bg);
  color: var(--text);
}

#app {
  background: var(--bg) !important;
  color: var(--text);
}

#app a {
  color: var(--accent);
}

#app a:hover {
  color: var(--accent-strong);
}

::selection {
  background: var(--accent);
  color: var(--accent-contrast);
}

::-webkit-scrollbar {
  width: 10px;
  height: 10px;
}

::-webkit-scrollbar-track {
  background: var(--scroll-track);
}

::-webkit-scrollbar-thumb {
  background: var(--scroll-thumb);
  border-radius: 5px;
}

/* 夜间：深色底上的 logo 反相，保证可见 */
:root[data-theme="night"] .askatek-logo,
:root[data-theme="night"] .askatek-logo1,
:root[data-theme="night"] .askatek-footer-wrapper-logo img,
:root[data-theme="night"] .header-logo img {
  filter: var(--logo-filter);
}

/* ---------------------------------------------------------------------------
   3. 切换过渡：仅切换瞬间挂 .theme-transition（300ms 缓动，背景与文字同步）
   ------------------------------------------------------------------------- */
html.theme-transition,
html.theme-transition *,
html.theme-transition *::before,
html.theme-transition *::after {
  transition:
    background-color 300ms ease,
    color 300ms ease,
    border-color 300ms ease,
    box-shadow 300ms ease,
    fill 300ms ease,
    stroke 300ms ease,
    opacity 300ms ease !important;
  transition-delay: 0s !important;
}

@media (prefers-reduced-motion: reduce) {
  html.theme-transition,
  html.theme-transition *,
  html.theme-transition *::before,
  html.theme-transition *::after {
    transition: none !important;
  }
}

/* ---------------------------------------------------------------------------
   4. 头部 / 导航
   ------------------------------------------------------------------------- */
.askatek-head,
.askatek-header {
  background-color: var(--header-bg);
  color: var(--header-text);
}

@media (min-width: 768px) {
  .askatek-header {
    background-color: var(--header-bg) !important;
  }
}

@media (max-width: 576px) {
  .askatek-header {
    background: var(--header-bg) !important;
    box-shadow: var(--shadow-sm);
  }
}

.scroll-top {
  background-color: var(--header-bg);
  box-shadow: var(--shadow-sm);
}

/* el-menu 横向导航（global.css 里写死了黑底白字，这里按令牌覆盖） */
.el-menu.el-menu--horizontal,
.el-menu.el-menu--horizontal .el-menu-item,
.el-menu.el-menu--horizontal .el-submenu__title,
.el-menu.el-menu--horizontal .el-submenu__title a,
.el-menu--horizontal .el-menu--popup,
.el-menu--horizontal .el-menu-item {
  background-color: var(--header-bg) !important;
  color: var(--header-text) !important;
}

.el-menu.el-menu--horizontal .el-menu-item:hover,
.el-menu.el-menu--horizontal .el-submenu__title:hover,
.el-menu--horizontal .el-menu-item:hover,
.el-menu--horizontal .el-menu-item:focus {
  background-color: var(--hover-bg) !important;
  color: var(--accent) !important;
}

.el-menu--horizontal .el-menu-item.is-active {
  color: var(--accent) !important;
  border-bottom-color: var(--accent) !important;
}

.el-menu--horizontal .el-menu--popup .el-menu-item:hover {
  background-color: var(--hover-bg) !important;
}

/* 搜索框 */
.header-search-toggle,
.header-btn-icon .el-input-group__append {
  color: var(--accent) !important;
  background: var(--surface) !important;
}

.header-search-toggle:hover {
  color: var(--accent-strong) !important;
}

.header-search-box .el-input-group {
  background: var(--input-bg);
  border-color: var(--border) !important;
}

.header-search-box .el-input-group__append {
  background: var(--surface-2) !important;
  color: var(--accent) !important;
  border-color: var(--border) !important;
}

.header-search-box .el-input__inner {
  background: var(--input-bg) !important;
  color: var(--text) !important;
}

.header-search-box .el-input__inner::placeholder {
  color: var(--text-faint);
}

/* 产品中心悬浮面板 */
.subNav {
  background: var(--surface) !important;
  box-shadow: var(--shadow) !important;
  border: 1px solid var(--border);
}

.subNav .subnav-top {
  border-bottom-color: var(--border);
}

.subNav .subnav-top-item {
  color: var(--text-muted);
}

.subNav .subnav-top-item:hover,
.subNav .subnav-top-item.active {
  color: var(--accent);
}

.subNav .subnav-top-item.active::after {
  background: var(--accent);
}

.subNav .subnav-col:nth-child(3n + 2),
.subNav .subnav-col:nth-child(3n) {
  border-left-color: var(--border);
}

.subNav .subnav-mid-name {
  color: var(--text-strong);
}

.subNav .subnav-mid-desc {
  color: var(--text-faint);
}

.subNav .subnav-list li {
  color: var(--text-muted);
}

.subNav .subnav-list li::before {
  background-color: var(--text-faint);
}

.subNav .subnav-list li:hover {
  color: var(--accent);
}

.subNav .subnav-list li:hover::before {
  background-color: var(--accent);
}

@media (max-width: 768px) {
  .subNav .subnav-col:not(:first-child) {
    border-top-color: var(--border);
  }
}

/* 移动端抽屉 */
.shading-menu {
  background: var(--bg) !important;
}

.shading-menu .shading-menu-login .menu-close {
  color: var(--text);
}

.shading-center-menu .el-menu .el-menu-item,
.shading-center-menu .el-menu .el-submenu__title {
  color: var(--text) !important;
  border-top-color: var(--border);
}

.shading-menu .shading-nav-item {
  border-top-color: var(--border);
}

.shading-menu .shading-nav-link,
.shading-menu .shading-nav-product .ptree-row {
  color: var(--text) !important;
}

.shading-menu .shading-nav-link:hover,
.shading-menu .shading-nav-sub li:hover {
