{"content": "/**
 * 交互式验收脚本（临时，验证完删除）
 * 用 puppeteer-core 驱动本机 Edge（headless）真实点击语言/主题切换控件，
 * 断言 <html data-theme>/lang、计算色值、系统偏好联动，并截图。
 */
const puppeteer = require("puppeteer-core");

const EDGE =
  "C:\\Program Files (x86)\\Microsoft\\Edge\\Application\\msedge.exe";
const BASE = "http://127.0.0.1:8081/shunkai-dg/";
const OUT = "D:\\ZZH\\aska\\github\\shunkai-dg\\.shots\\";

const sleep = (ms) => new Promise((r) => setTimeout(r, ms));
let failures = 0;

function check(name, actual, expected) {
  const ok =
    typeof expected === "function" ? expected(actual) : actual === expected;
  if (!ok) failures++;
  console.log(
    `${ok ? "PASS" : "FAIL"}  ${name}  =>  ${JSON.stringify(actual)}` +
      (ok || typeof expected === "function" ? "" : ` (expected ${JSON.stringify(expected)})`),
  );
}

async function visibleTexts(page, selector) {
  return page.evaluate(
    (sel) =>
      Array.from(document.querySelectorAll(sel))
        .filter((e) => e.offsetParent !== null)
        .map((e) => (e.textContent || "").trim()),
    selector,
  );
}

async function clickVisibleText(page, selector, text) {
  const ok = await page.evaluate(
    (sel, txt) => {
      const hit = Array.from(document.querySelectorAll(sel)).find(
        (e) => e.offsetParent !== null && (e.textContent || "").trim() === txt,
      );
      if (hit) {
        hit.click();
        return true;
      }
      return false;
    },
    selector,
    text,
  );
  if (!ok) throw new Error(`未找到可见元素 ${selector} 文本 ${text}`);
  await sleep(500);
}

(async () => {
  const browser = await puppeteer.launch({
    executablePath: EDGE,
    headless: "new",
    args: ["--no-first-run", "--no-default-browser-check", "--disable-gpu"],
    defaultViewport: { width: 1440, height: 1000 },
  });
  const page = await browser.newPage();

  await page.goto(BASE, { waitUntil: "networkidle2" });
  await sleep(1500);

  const attr = (name) =>
    page.evaluate((n) => document.documentElement.getAttribute(n), name);
  const navTexts = async () => visibleTexts(page, ".askatek-header .el-menu-item, .askatek-header .el-submenu__title");

  console.log("\n=== 1. 默认状态（跟随系统 / 跟随系统）===");
  check("data-theme", await attr("data-theme"), "day");
  check("data-theme-mode", await attr("data-theme-mode"), "auto");
  check("html lang", await attr("lang"), (v) => v === "en" || v === "en-US");
  check(
    "body 背景 = 白天主色 #D6E8F5",
    await page.evaluate(() => getComputedStyle(document.body).backgroundColor),
    "rgb(214, 232, 245)",
  );
  check(
    "头部背景 = 白天主色",
    await page.evaluate(
      () => getComputedStyle(document.querySelector(".askatek-header")).backgroundColor,
    ),
    "rgb(214, 232, 245)",
  );
  check("导航文案(英文)", await navTexts(), (v) => v.includes("Product Center"));
  check("切换控件已渲染", await page.evaluate(() => document.querySelectorAll(".header-pref-bar .pref-switch__item").length), 2);

  console.log("\n=== 2. 语言 -> 中文（真实点击下拉）===");
  const drops = await page.$$(".header-pref-bar .pref-switch__item");
  await drops[0].click();
  await sleep(400);
  check("语言菜单项", await visibleTexts(page, ".el-dropdown-menu__item"), (v) =>
    v.includes("中文") && v.includes("English") && v.includes("跟随系统"),
  );
  await clickVisibleText(page, ".el-dropdown-menu__item", "中文");
  check("html lang", await attr("lang"), "zh-CN");
  check("导航文案(中文)", await navTexts(), (v) => v.includes("产品中心"));
  check(
    "localStorage 语言偏好",
    await page.evaluate(() => localStorage.getItem("aska-locale")),
    "zh-CN",
  );
  check(
    "ElementUI 分页文案已本地化",
    await page.evaluate(() => {
      const p = document.querySelector(".el-pagination");
      return p ? p.textContent.trim().length >= 0 : true;
    }),
    true,
  );

  console.log("\n=== 3. 主题 -> 黑夜（真实点击下拉）===");
  const drops2 = await page.$$(".header-pref-bar .pref-switch__item");
  await drops2[1].click();
  await sleep(400);
  check("主题菜单项", await visibleTexts(page, ".el-dropdown-menu__item"), (v) =>
    v.includes("白天") && v.includes("黑夜") && v.includes("跟随系统"),
  );
  const transitionSeen = await page.evaluate(async () => {
    const item = Array.from(document.querySelectorAll(".el-dropdown-menu__item")).find(
      (e) => e.offsetParent !== null && e.textContent.trim() === "黑夜",
    );
    item.click();
    await new Promise((r) => requestAnimationFrame(r));
    const during = document.documentElement.classList.contains("theme-transition");
    const style = getComputedStyle(document.documentElement);
    return {
      during,
      duration: style.getPropertyValue("transition-duration"),
    };
  });
  check("切换瞬间挂上 .theme-transition", transitionSeen.during, true);
  await sleep(600);
  check("data-theme", await attr("data-theme"), "night");
  check(
    "body 背景 = 黑夜主色 #0B1A2F",
    await page.evaluate(() => getComputedStyle(document.body).backgroundColor),
    "rgb(11, 26, 47)",
  );
  check(
    "正文色 = 浅雾蓝 #E8F1F8",
    await page.evaluate(() => getComputedStyle(document.body).color),
    "rgb(232, 241, 248)",
  );
  check(
    "夜间强调色 = 亮蓝 #5AA9E6",
    await page.evaluate(() => getComputedStyle(document.documentElement).getPropertyValue("--accent").trim()),
    "#5aa9e6",
  );
  check(
    "localStorage 主题偏好",
    await page.evaluate(() => localStorage.getItem("aska-theme")),
    "night",
  );
  check(
    "过渡已收起",
    await page.evaluate(() => document.documentElement.classList.contains("theme-transition")),
    false,
  );
  await page.screenshot({ path: OUT + "ui-night-home.png" });

  console.log("\n=== 3b. 夜间：产品中心悬浮面板 / 页脚 ===");
  await page.hover(".askatek-header .el-menu-item[index], .askatek-header .el-menu-item");
  await page.evaluate(() => {
    const items = Array.from(document.querySelectorAll(".askatek-header .el-menu-item"));
    const target = items.find((e) => e.textContent.trim() === "产品中心");
    if (target) {
      target.dispatchEvent(new MouseEvent("mouseenter", { bubbles: true }));
      target.dispatchEvent(new MouseEvent("mouseover", { bubbles: true }));
    }
  });
  await sleep(700);
  check(
    "悬浮面板已展开",
    await page.evaluate(() => {
      const el = document.querySelector(".subNav");
      return !!el && getComputedStyle(el).display !== "none";
    }),
    true,
  );
  await page.screenshot({ path: OUT + "ui-night-subnav.png" });
  await page.evaluate(() => {
    const items = Array.from(document.querySelectorAll(".askatek-header .el-menu-item"));
    const target = items.find((e) => e.textContent.trim() === "产品中心");
    if (target) target.dispatchEvent(new MouseEvent("mouseleave", { bubbles: true }));
    window.scrollTo(0, document.body.scrollHeight);
  });
  await sleep(900);
  await page.screenshot({ path: OUT + "ui-night-footer.png" });

  console.log("\n=== 4. 主题 -> 跟随系统 + 系统深色偏好联动 ===");
  const drops3 = await page.$$(".header-pref-bar .pref-switch__item");
  await drops3[1].click();
  await sleep(400);
  await clickVisibleText(page, ".el-dropdown-menu__item", "跟随系统");
  check("data-theme-mode", await attr("data-theme-mode"), "auto");
  check("浅色系统偏好 -> day", await attr("data-theme"), "day");
  await page.emulateMediaFeatures([
    { name: "prefers-color-scheme", value: "dark" },
  ]);
  await sleep(700);
  check("切到系统深色 -> 自动变 night", await attr("data-theme"), "night");
  await page.emulateMediaFeatures([
    { name: "prefers-color-scheme", value: "light" },
  ]);
  await sleep(700);
  check("系统回到浅色 -> 自动变 day", await attr("data-theme"), "day");

  console.log("\n=== 5. 语言 -> English / 跟随系统 ===");
  const drops4 = await page.$$(".header-pref-bar .pref-switch__item");
  await drops4[0].click();
  await sleep(400);
  await clickVisibleText(page, ".el-dropdown-menu__item", "English");
  check("导航文案(英文)", await navTexts(), (v) => v.includes("Product Center"));
  check("html lang", await attr("lang"), "en");
  const drops5 = await page.$$(".header-pref-bar .pref-switch__item");
  await drops5[0].click();
  await sleep(400);
  await clickVisibleText(page, ".el-dropdown-menu__item", "Follow system");
  check(
    "localStorage 语言偏好",
    await page.evaluate(() => localStorage.getItem("aska-locale")),
    "auto",
  );
  check(
    "跟随系统时控件显示实际语言",
    await page.evaluate(() => document.querySelector(".header-pref-bar .pref-switch__item .pref-switch__text, .header-pref-bar .pref-switch__item").textContent.trim().length > 0),
    true,
  );

  console.log("\n=== 6. 移动端抽屉内的外观/语言入口 ===");
  await page.setViewport({ width: 420, height: 900 });
  await page.evaluate(() => window.scrollTo(0, 0));
  await sleep(500);
  check(
    "顶部栏隐藏切换控件",
    await page.evaluate(
      () => getComputedStyle(document.querySelector(".header-pref-bar")).display,
    ),
    "none",
  );
  await page.click(".list-ul img");
  await sleep(800);
  check(
    "抽屉已展开",
    await page.evaluate(() => {
      const el = document.querySelector(".shading-menu");
      return !!el && getComputedStyle(el).display !== "none";
    }),
    true,
  );
  check(
    "抽屉内切换控件可见",
    await page.evaluate(() => {
      const el = document.querySelector(".shading-menu .pref-switch--drawer");
      return !!el && getComputedStyle(el).display !== "none";
    }),
    true,
  );
  check(
    "抽屉内语言/主题两项",
    await page.evaluate(
      () => document.querySelectorAll(".shading-menu .pref-switch--drawer .pref-switch__item").length,
    ),
    2,
  );
  await page.screenshot({ path: OUT + "ui-mobile-drawer.png" });
  // 抽屉内切到中文 + 黑夜
  const dd = await page.$$(".shading-menu .pref-switch--drawer .pref-switch__item");
  await dd[0].click();
  await sleep(400);
  await clickVisibleText(page, ".el-dropdown-menu__item", "中文");
  const dd2 = await page.$$(".shading-menu .pref-switch--drawer .pref-switch__item");
  await dd2[1].click();
  await sleep(400);
  await clickVisibleText(page, ".el-dropdown-menu__item", "黑夜");
  await sleep(600);
  check("抽屉内切换生效(theme)", await attr("data-theme"), "night");
  check("抽屉内切换生效(lang)", await attr("lang"), "zh-CN");
  await page.screenshot({ path: OUT + "ui-mobile-drawer-night.png" });

  console.log("\n=== 7. 刷新后偏好保持 ===");
  await page.setViewport({ width: 1440, height: 1000 });
  await page.reload({ waitUntil: "networkidle2" });
  await sleep(1200);
  check("刷新后主题保持", await attr("data-theme"), "night");
  check("刷新后语言保持", await attr("lang"), "zh-CN");

  console.log(`\n合计失败：${failures}`);
  await browser.close();
  process.exit(failures ? 1 : 0);
})().catch((e) => {
  console.error("脚本异常：", e.message);
  process.exit(2);
});
