{"content": "const puppeteer = require("puppeteer-core");
const EDGE = "C:\\Program Files (x86)\\Microsoft\\Edge\\Application\\msedge.exe";
const BASE = "http://127.0.0.1:8081/shunkai-dg/";
const sleep = (ms) => new Promise((r) => setTimeout(r, ms));

(async () => {
  const browser = await puppeteer.launch({
    executablePath: EDGE,
    headless: "new",
    args: ["--no-first-run", "--no-default-browser-check", "--disable-gpu"],
    defaultViewport: { width: 1440, height: 1000 },
  });
  const page = await browser.newPage();
  page.on("console", (m) => console.log("[console:" + m.type() + "]", m.text()));
  page.on("pageerror", (e) => console.log("[pageerror]", e.message));
  page.on("requestfailed", (r) => console.log("[reqfail]", r.url(), r.failure() && r.failure().errorText));
  await page.goto(BASE, { waitUntil: "networkidle2" });
  await sleep(2000);
  const info = await page.evaluate(() => ({
    appHtmlLength: (document.getElementById("app") || {}).innerHTML
      ? document.getElementById("app").innerHTML.length
      : 0,
    appChildren: document.getElementById("app") ? document.getElementById("app").children.length : -1,
    classes: document.getElementById("app")
      ? Array.from(document.getElementById("app").children).map((c) => c.className)
      : [],
    lang: document.documentElement.lang,
    theme: document.documentElement.getAttribute("data-theme"),
    navText: document.body.innerText.slice(0, 300),
  }));
  console.log(JSON.stringify(info, null, 2));
  await browser.close();
})();
