{"content": "/**
 * 对比度审计（临时）：逐页 × 逐主题，统计正文/次要文字相对实际背景的对比度，
 * 报出 < 4.5 的项（WCAG AA 正文阈值）。跳过背景为图片的容器（海报文案另行人工确认）。
 */
const puppeteer = require("puppeteer-core");

const EDGE = "C:\\Program Files (x86)\\Microsoft\\Edge\\Application\\msedge.exe";
const BASE = "http://127.0.0.1:8081/shunkai-dg/";
const sleep = (ms) => new Promise((r) => setTimeout(r, ms));

const ROUTES = [
  ["home", "#/"],
  ["about", "#/about-aska"],
  ["product-center", "#/product-center"],
  ["product-detail", "#/product-center/detail?id=17&hierarchy=29"],
  ["product-list", "#/product-list?k=head"],
  ["rd-center", "#/r-d-center"],
  ["news", "#/news"],
  ["news-detail", "#/news/detail?id=1"],
  ["production", "#/production"],
  ["join", "#/join-us"],
  ["join-detail", "#/join-us/details?id=1"],
  ["contact", "#/contact-us"],
];

const AUDIT = () => {
  const parse = (c) => {
    const m = /rgba?\(([^)]+)\)/.exec(c || "");
    if (!m) return null;
    const p = m[1].split(",").map((s) => parseFloat(s));
    return { r: p[0], g: p[1], b: p[2], a: p.length > 3 ? p[3] : 1 };
  };
  const L = ({ r, g, b }) => {
    const f = (v) => {
      v /= 255;
      return v <= 0.03928 ? v / 12.92 : Math.pow((v + 0.055) / 1.055, 2.4);
    };
    return 0.2126 * f(r) + 0.7152 * f(g) + 0.0722 * f(b);
  };
  const ratio = (a, b) => {
    const la = L(a);
    const lb = L(b);
    const hi = Math.max(la, lb);
    const lo = Math.min(la, lb);
    return (hi + 0.05) / (lo + 0.05);
  };
  const bgOf = (el) => {
    let node = el;
    while (node && node.nodeType === 1) {
      const cs = getComputedStyle(node);
      if (cs.backgroundImage && cs.backgroundImage !== "none") return null;
      const bg = parse(cs.backgroundColor);
      if (bg && bg.a > 0.85) return bg;
      node = node.parentElement;
    }
    return parse(getComputedStyle(document.body).backgroundColor);
  };
  const out = [];
  const nodes = document.querySelectorAll("#app *");
  nodes.forEach((el) => {
    if (!el.offsetParent) return;
    const own = Array.from(el.childNodes)
      .filter((n) => n.nodeType === 3)
      .map((n) => n.textContent.trim())
      .join(" ")
      .trim();
    if (!own) return;
    const cs = getComputedStyle(el);
    const fg = parse(cs.color);
    if (!fg || fg.a < 0.4) return;
    const bg = bgOf(el);
    if (!bg) return;
    const r = ratio(fg, bg);
    const px = parseFloat(cs.fontSize);
    const bold = parseInt(cs.fontWeight, 10) >= 700;
    // 大号字（>=18.66px bold 或 >=24px）AA 阈值为 3:1
    const limit = px >= 24 || (bold && px >= 18.66) ? 3 : 4.5;
    if (r < limit) {
      out.push({
        text: own.slice(0, 34),
        cls: (el.className || "").toString().slice(0, 70),
        ratio: Math.round(r * 100) / 100,
        fg: cs.color,
        bg: `rgb(${Math.round(bg.r)},${Math.round(bg.g)},${Math.round(bg.b)})`,
        px: Math.round(px),
      });
    }
  });
  return out;
};

(async () => {
  const browser = await puppeteer.launch({
    executablePath: EDGE,
    headless: "new",
    args: ["--no-first-run", "--no-default-browser-check", "--disable-gpu"],
    defaultViewport: { width: 1440, height: 1400 },
  });
  const page = await browser.newPage();
  await page.setRequestInterception(true);
  page.on("request", (req) => {
    const url = req.url();
    if (url.startsWith("http://localhost:8080/img_data/")) {
      req.continue({ url: url.replace("localhost:8080", "127.0.0.1:8081") });
    } else req.continue();
  });

  const summary = {};
  for (const theme of ["day", "night"]) {
    summary[theme] = {};
    for (const [name, hash] of ROUTES) {
      // 直接写 localStorage 不可行（跨域无关，但需在导航前设置），改用 URL 覆盖
      const url = `${BASE}?theme=${theme}&locale=zh-CN${hash}`;
      await page.goto(url, { waitUntil: "networkidle2" });
      await sleep(1400);
      await page.evaluate(() =>
        window.scrollTo(0, Math.max(document.body.scrollHeight, 1200) / 2),
      );
      await sleep(700);
      const offenders = await page.evaluate(AUDIT);
      // 汇总：按 类名+前景/背景 去重
      const seen = new Map();
      offenders.forEach((o) => {
        const key = `${o.cls}|${o.fg}|${o.bg}|${o.px}`;
        if (!seen.has(key)) seen.set(key, { ...o, count: 1 });
        else seen.get(key).count++;
      });
      summary[theme][name] = Array.from(seen.values());
      console.log(
        `\n### ${theme} / ${name}  (${offenders.length} 处低于阈值, ${seen.size} 类)`,
      );
      Array.from(seen.values())
        .slice(0, 12)
        .forEach((o) =>
          console.log(
            `   ${String(o.ratio).padEnd(6)} ${o.px}px  fg=${o.fg} bg=${o.bg}  .${o.cls}  «${o.text}»  x${o.count}`,
          ),
        );
    }
  }
  await browser.close();
  const fs = require("fs");
  fs.writeFileSync(
    "D:\\ZZH\\aska\\github\\shunkai-dg\\.shots\\contrast-report.json",
    JSON.stringify(summary, null, 2),
  );
})();
", "file_path": "D:\ZZH\aska\github\shunkai-dg\.shots\audit-contrast.js"}

