content.arguments:
{"command": "$files = @("src\assets\css\theme.css", "src\assets\css\global.css", "src\assets\css\header.scss")
foreach ($p in $files) {
  $c = Get-Content $p -Raw -Encoding UTF8
  $eol = if ($c.Contains("`r`n")) { "`r`n" } else { "`n" }
  $lines = $c -split "`r?`n"
  $n = 0
  for ($i = 0; $i -lt $lines.Count; $i++) {
    if ($lines[$i] -match '^(\s*)color:\s*var\(--accent\)(\s*!important)?;') {
      $lines[$i] = $lines[$i] -replace 'var\(--accent\)', 'var(--accent-text)'
      $n++
    }
  }
  Set-Content -Path $p -Value ($lines -join $eol) -Encoding UTF8 -NoNewline
  "{0}: 文本色改用 --accent-text 共 {1} 行" -f $p, $n
}
"--- 剩余 color: var(--accent) 出现位置（应仅剩结构性/大号场景）:"
Select-String -Path $files -Pattern 'color:\s*var\(--accent\)' | ForEach-Object { "{0}:{1}: {2}" -f (Split-Path $_.Path -Leaf), $_.LineNumber, $_.Line.Trim() }", "description": "Switch small-text accent colors to AA variant"}

