content.arguments:
{"command": "$map = Get-Content ".shots\view-token-map.json" -Raw -Encoding UTF8 | ConvertFrom-Json
$errors = @()
$totalChanged = 0
foreach ($file in $map.PSObject.Properties) {
  $p = $file.Name
  $c = Get-Content $p -Raw -Encoding UTF8
  $eol = if ($c.Contains("`r`n")) { "`r`n" } else { "`n" }
  $lines = $c -split "`r?`n"
  $changed = 0
  foreach ($ln in $file.Value.PSObject.Properties) {
    $idx = [int]$ln.Name - 1
    $from = $ln.Value[0]; $to = $ln.Value[1]
    if ($idx -ge $lines.Count) { $errors += "$p`:$($ln.Name) 行号越界"; continue }
    if ($lines[$idx].Contains($from)) {
      $lines[$idx] = $lines[$idx].Replace($from, $to)
      $changed++
    } else { $errors += "$p`:$($ln.Name) 未匹配 «$from» 实际: $($lines[$idx].Trim())" }
  }
  Set-Content -Path $p -Value ($lines -join $eol) -Encoding UTF8 -NoNewline
  $totalChanged += $changed
  "{0}: {1} 行" -f $p, $changed
}
"`n合计替换 $totalChanged 行；未匹配 $($errors.Count) 处"
$errors", "description": "Apply theme token mapping to view styles"}

