{"content": "const puppeteer = require("puppeteer-core");
const EDGE = "C:\\Program Files (x86)\\Microsoft\\Edge\\Application\\msedge.exe";
const BASE = "http://127.0.0.1:8081/shunkai-dg/";
const sleep = (ms) => new Promise((r) => setTimeout(r, ms));

const PROBES = [
  ["about", "#/about-aska", ".breadcrumb .parent"],
  ["news", "#/news", ".new_item_r_desc"],
  ["product-center", "#/product-center", ".el-pager .number"],
  ["news-detail", "#/news/detail?id=1", ".rich-content, .news_detail_content, .content"],
  ["join-detail", "#/join-us/details?id=1", ".rich-content, .content"],
];

(async () => {
  const browser = await puppeteer.launch({
    executablePath: EDGE,
    headless: "new",
    args: ["--no-first-run", "--no-default-browser-check", "--disable-gpu"],
    defaultViewport: { width: 1440, height: 1200 },
  });
  const page = await browser.newPage();
  await page.setRequestInterception(true);
  page.on("request", (req) => {
    const u = req.url();
    if (u.startsWith("http://localhost:8080/img_data/"))
      req.continue({ url: u.replace("localhost:8080", "127.0.0.1:8081") });
    else req.continue();
  });

  for (const [name, hash, sel] of PROBES) {
    await page.goto(`${BASE}?theme=night&locale=zh-CN${hash}`, {
      waitUntil: "networkidle2",
    });
    await sleep(1300);
    const info = await page.evaluate((s) => {
      const el = document.querySelector(s);
      if (!el) return { found: false };
      const chain = [];
      let node = el;
      while (node && node.nodeType === 1) {
        const cs = getComputedStyle(node);
        chain.push({
          tag: node.tagName.toLowerCase(),
