{"command": "$map = Get-Content ".shots\rich-token-map.json" -Raw -Encoding UTF8 | ConvertFrom-Json
$errors = @()
foreach ($file in $map.PSObject.Properties) {
  $p = $file.Name
  $c = Get-Content $p -Raw -Encoding UTF8
  $eol = if ($c.Contains("`r`n")) { "`r`n" } else { "`n" }
  $lines = $c -split "`r?`n"
  $changed = 0
  foreach ($ln in $file.Value.PSObject.Properties) {
    $idx = [int]$ln.Name - 1
    $from = $ln.Value[0]; $to = $ln.Value[1]
    if ($idx -lt $lines.Count -and $lines[$idx].Contains($from)) { $lines[$idx] = $lines[$idx].Replace($from, $to); $changed++ }
    else { $errors += "$p`:$($ln.Name) 未匹配 «$from»" }
  }
  Set-Content -Path $p -Value ($lines -join $eol) -Encoding UTF8 -NoNewline
  "{0}: {1} 行" -f $p, $changed
}
"未匹配 $($errors.Count)"; $errors", "description": "Apply token mapping to rich content styles"}

