   注：Breadcrumb 组件自带 .breadcrumb_bg{background:#fff!important}，
   组件样式在运行时注入，晚于主包，故这里提升一级特异性（html[data-theme] 前缀） */
html[data-theme] .breadcrumb {
  background: var(--bg) !important;
  border-bottom-color: var(--border) !important;
}

html[data-theme] .breadcrumb_bg {
  background: var(--bg-soft) !important;
  border-color: transparent !important;
}

.breadcrumb .no-redirect,
.breadcrumb .parent,
.el-breadcrumb__inner {
  color: var(--text-muted) !important;
}

.breadcrumb .no-redirect {
  color: var(--accent-text) !important;
}

.breadcrumb .parent:hover {
  color: var(--accent-text) !important;
}

.breadcrumb .el-breadcrumb__separator {
  color: var(--text-faint) !important;
}", "old_string": "/* 面包屑 & 回到顶部 */
