{"command": "foreach ($p in @("src\views\news\News.vue", "src\views\join\JoinUsDetail.vue")) {
  $c = Get-Content $p -Raw -Encoding UTF8
  $eol = if ($c.Contains("`r`n")) { "`r`n" } else { "`n" }
  $lines = $c -split "`r?`n"
  $n = 0
  for ($i = 0; $i -lt $lines.Count; $i++) { if ($lines[$i] -match '^(\s*)color:\s*grey\s*;') { $lines[$i] = $lines[$i] -replace 'grey', 'var(--text-muted)'; $n++ } }
  Set-Content -Path $p -Value ($lines -join $eol) -Encoding UTF8 -NoNewline
  "{0}: {1} 行" -f $p, $n
}
Start-Sleep -Seconds 8
node .shots\audit-contrast.js 2>&1 | Select-Object -First 60", "description": "Replace grey keyword and re-audit", "timeoutMs": 600000}

