{"content": "/** 临时静态服务器（仅用于产线构建冒烟验证，验证完即关闭）：端口 8090 */
const http = require("http");
const fs = require("fs");
const path = require("path");

const ROOT = "D:\\ZZH\\aska\\github\\shunkai-dg\\dist";
const PREFIX = "/shunkai-dg";
const TYPES = {
  ".html": "text/html; charset=utf-8",
  ".js": "application/javascript; charset=utf-8",
  ".css": "text/css; charset=utf-8",
  ".png": "image/png",
  ".jpg": "image/jpeg",
  ".jpeg": "image/jpeg",
  ".svg": "image/svg+xml",
  ".json": "application/json; charset=utf-8",
  ".ico": "image/x-icon",
  ".gif": "image/gif",
};

http
  .createServer((req, res) => {
    let url = decodeURIComponent(req.url.split("?")[0]);
    if (url.startsWith(PREFIX)) url = url.slice(PREFIX.length);
    if (url === "/img_data" || url.startsWith("/img_data/")) {
      // RESOURCE_BASE_URL 指向 8080，这里顺带兼容根路径访问
    }
    if (url === "/" || url === "") url = "/index.html";
    const file = path.join(ROOT, url);
    if (!file.startsWith(ROOT) || !fs.existsSync(file) || fs.statSync(file).isDirectory()) {
      res.writeHead(404);
      res.end("not found: " + url);
      return;
    }
    res.writeHead(200, { "Content-Type": TYPES[path.extname(file)] || "application/octet-stream" });
    fs.createReadStream(file).pipe(res);
  })
  .listen(8090, "127.0.0.1", () => console.log("dist server on http://127.0.0.1:8090/shunkai-dg/"));
", "file_path": "D:\ZZH\aska\github\shunkai-dg\.shots\serve-dist.js"}

