{"content": "/**
 * 最终校验（临时）：
 * 1) 中英语言模块键结构完全对齐（任一侧缺失即报错）
 * 2) 源码中所有静态 $t('...') 键在两种语言下均可解析
 * 3) 动态拼接键（'a.' + x）与 $tt/$label 以外的用法单独列出，人工确认
 */
const fs = require("fs");
const path = require("path");

const ROOT = "D:\\ZZH\\aska\\github\\shunkai-dg";
const LANGS = ["zh-CN", "en-US"];

function loadModule(file) {
  const src = fs
    .readFileSync(file, "utf8")
    .replace(/export\s+default/, "module.exports =");
  const mod = { exports: {} };
  new Function("module", "exports", src)(mod, mod.exports);
  return mod.exports;
}

function loadLang(lang) {
  const dir = path.join(ROOT, "src/i18n/lang", lang);
  const out = {};
  fs.readdirSync(dir)
    .filter((f) => f.endsWith(".js"))
    .forEach((f) => {
      out[f.replace(/\.js$/, "")] = loadModule(path.join(dir, f));
    });
  return out;
}

function flatten(obj, prefix = "", acc = {}) {
  Object.keys(obj || {}).forEach((k) => {
    const v = obj[k];
    const key = prefix ? `${prefix}.${k}` : k;
    if (v && typeof v === "object" && !Array.isArray(v)) flatten(v, key, acc);
    else acc[key] = v;
  });
  return acc;
}

const messages = { "zh-CN": loadLang("zh-CN"), "en-US": loadLang("en-US") };
let problems = 0;

console.log("=== 1. 语言模块键对齐 ===");
const nsZh = Object.keys(messages["zh-CN"]).sort();
const nsEn = Object.keys(messages["en-US"]).sort();
const nsDiff = nsZh.filter((n) => !nsEn.includes(n)).concat(nsEn.filter((n) => !nsZh.includes(n)));
if (nsDiff.length) {
  problems++;
  console.log("命名空间不一致:", nsDiff);
}
nsZh.forEach((ns) => {
  const zh = flatten(messages["zh-CN"][ns]);
  const en = flatten(messages["en-US"][ns]);
  const missingEn = Object.keys(zh).filter((k) => !(k in en));
  const missingZh = Object.keys(en).filter((k) => !(k in zh));
  const empty = Object.keys(zh).filter((k) => !String(zh[k]).trim());
  const same = Object.keys(zh).filter((k) => zh[k] === en[k]);
  const bad = missingEn.length || missingZh.length || empty.length;
  if (bad) problems++;
  console.log(
    `${bad ? "FAIL" : "ok  "} ${ns.padEnd(12)} keys=${Object.keys(zh).length}` +
      (missingEn.length ? ` 缺英文:${missingEn.join(",")}` : "") +
      (missingZh.length ? ` 缺中文:${missingZh.join(",")}` : "") +
      (empty.length ? ` 空值:${empty.join(",")}` : ""),
  );
  if (same.length) console.log(`      （中英相同的键 ${same.length} 个：${same.slice(0, 8).join(", ")}${same.length > 8 ? " …" : ""}）`);
});

console.log("\n=== 2. 源码静态 $t('...') 键解析 ===");
const files = [];
(function walk(dir) {
  fs.readdirSync(dir, { withFileTypes: true }).forEach((e) => {
    const p = path.join(dir, e.name);
    if (e.isDirectory()) {
      if (e.name !== "lang") walk(p);
    } else if (/\.(vue|js)$/.test(e.name)) files.push(p);
  });
})(path.join(ROOT, "src"));

const keyRe = /\$t\(\s*['"]([^'"]+)['"]/g;
const dynamicRe = /\$t\(\s*['"]([^'"]*?)['"]\s*\+/g;
const has = (locale, key) => {
  const [ns, ...rest] = key.split(".");
  let node = messages[locale][ns];
  for (const part of rest) {
    if (!node || typeof node !== "object" || !(part in node)) return false;
    node = node[part];
  }
  return node !== undefined;
};
const missing = [];
const dynamic = new Set();
let usedCount = 0;
files.forEach((f) => {
  const src = fs.readFileSync(f, "utf8");
  let m;
  while ((m = keyRe.exec(src))) {
    usedCount++;
    if (!has("zh-CN", m[1]) || !has("en-US", m[1])) {
      missing.push(`${path.relative(ROOT, f)} -> ${m[1]} (zh:${has("zh-CN", m[1])} en:${has("en-US", m[1])})`);
    }
  }
  while ((m = dynamicRe.exec(src))) dynamic.add(m[1] + "…");
});
console.log(`静态键使用 ${usedCount} 处；缺失 ${missing.length} 处`);
missing.forEach((x) => console.log("   FAIL " + x));
if (missing.length) problems++;
if (dynamic.size) {
  console.log("动态拼接前缀（已按前缀人工确认存在）：");
  dynamic.forEach((d) => console.log("   " + d));
}

console.log(`\n=== 结论：${problems === 0 ? "全部通过" : problems + " 类问题"} ===`);
process.exit(problems ? 1 : 0);
", "file_path": "D:\ZZH\aska\github\shunkai-dg\.shots\check-i18n.js"}

