{"content": "/** 预览截图（临时）：白天/黑夜首页 + 移动端抽屉内切换控件 */
const puppeteer = require("puppeteer-core");
const EDGE = "C:\\Program Files (x86)\\Microsoft\\Edge\\Application\\msedge.exe";
const BASE = "http://127.0.0.1:8081/shunkai-dg/";
const OUT = "D:\\ZZH\\aska\\github\\shunkai-dg\\.preview\\";
const sleep = (ms) => new Promise((r) => setTimeout(r, ms));

(async () => {
  const browser = await puppeteer.launch({
    executablePath: EDGE,
    headless: "new",
    args: ["--no-first-run", "--no-default-browser-check", "--disable-gpu"],
    defaultViewport: { width: 1360, height: 900 },
  });
  const page = await browser.newPage();
  await page.setRequestInterception(true);
  page.on("request", (req) => {
    const u = req.url();
    if (u.startsWith("http://localhost:8080/img_data/"))
      req.continue({ url: u.replace("localhost:8080", "127.0.0.1:8081") });
    else req.continue();
  });

  // 白天 + 中文
  await page.goto(`${BASE}?theme=day&locale=zh-CN#/`, { waitUntil: "networkidle2" });
  await sleep(1800);
  await page.screenshot({ path: OUT + "theme-day-zh.png" });

  // 黑夜 + 中文，并打开移动端抽屉展示切换控件
  await page.setViewport({ width: 420, height: 820 });
  await page.goto(`${BASE}?theme=night&locale=zh-CN#/`, { waitUntil: "networkidle2" });
  await sleep(1600);
  await page.click(".list-ul img");
  await sleep(900);
  await page.screenshot({ path: OUT + "theme-night-mobile-drawer.png" });

  // 黑夜首页（桌面）
  await page.setViewport({ width: 1360, height: 900 });
  await page.goto(`${BASE}?theme=night&locale=zh-CN#/`, { waitUntil: "networkidle2" });
  await sleep(1800);
  await page.screenshot({ path: OUT + "theme-night-zh.png" });

  // 白天 + 英文（对照）
  await page.goto(`${BASE}?theme=day&locale=en-US#/product-center`, { waitUntil: "networkidle2" });
  await sleep(1600);
  await page.screenshot({ path: OUT + "theme-day-en-product.png" });

  console.log("done");
  await browser.close();
})();
", "file_path": "D:\ZZH\aska\github\shunkai-dg\.preview\shoot.js"}

